// cdb_tpch: loads TPC-H data (generated by tools/tpch_data.py) and times the supported queries.
//
//   cdb_tpch --sf 1 [--queries 1,3,6] [--runs 5] [--data DIR] [--no-optimizer]
//
// Prints load times and, per query, the row count and the minimum / median wall time over the runs
// (the first run is reported separately as "cold"). A run is Connection::Query end to end: parse,
// bind, optimize, plan, execute, materialise the result. Correctness is checked by the TPC-H
// differential test (CDB_TPCH_SF=<sf> build/<preset>/tests/cdb_tests --gtest_filter='*Tpch*'),
// not here; the row count is printed as a sanity check against DuckDB's answer file.

#include "main/connection.h"
#include "main/database.h"

#include <sys/resource.h>

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

namespace {

double Seconds(std::chrono::steady_clock::duration d) {
    return std::chrono::duration<double>(d).count();
}

std::string ReadFile(const std::string& path) {
    std::ifstream in(path);
    std::stringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

long MaxRssMb() {
    rusage usage{};
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_maxrss / 1024; // KiB on Linux
}

size_t ExpectedRows(const std::string& path) {
    std::ifstream in(path);
    size_t n = 0;
    for (std::string line; std::getline(in, line);) {
        n++;
    }
    return n;
}

} // namespace

int main(int argc, char** argv) {
    double sf = 0.01;
    std::string data_dir;
    std::vector<int> queries = {1, 3, 5, 6, 7, 8, 9, 10, 12, 13, 14, 19};
    int runs = 5;
    bool optimizer = true;
    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        if (a == "--sf" && i + 1 < argc) {
            sf = std::atof(argv[++i]);
        } else if (a == "--data" && i + 1 < argc) {
            data_dir = argv[++i];
        } else if (a == "--runs" && i + 1 < argc) {
            runs = std::atoi(argv[++i]);
        } else if (a == "--no-optimizer") {
            optimizer = false;
        } else if (a == "--queries" && i + 1 < argc) {
            queries.clear();
            std::stringstream ss(argv[++i]);
            for (std::string q; std::getline(ss, q, ',');) {
                queries.push_back(std::atoi(q.c_str()));
            }
        } else {
            std::cerr << "usage: cdb_tpch --sf N [--queries 1,3,6] [--runs N] [--data DIR] "
                         "[--no-optimizer]\n";
            return 2;
        }
    }
    char sf_text[32];
    std::snprintf(sf_text, sizeof sf_text, "%g", sf);
    if (data_dir.empty()) {
        data_dir = std::string(CDB_SOURCE_DIR) + "/data/tpch-sf" + sf_text;
    }

    cdb::Database db;
    cdb::Connection conn(db);
    conn.SetOptimizerEnabled(optimizer);
    {
        const cdb::QueryResult r =
            conn.Query(ReadFile(std::string(CDB_SOURCE_DIR) + "/bench/tpch/schema.sql"));
        if (!r.ok()) {
            std::cerr << "schema: " << r.error_message() << "\n";
            return 1;
        }
    }
    std::printf("TPC-H SF%s, %d run(s) per query, optimizer %s\n\nload:\n", sf_text, runs,
                optimizer ? "on" : "off");
    const char* const tables[] = {"nation",   "region",   "part",   "supplier",
                                  "partsupp", "customer", "orders", "lineitem"};
    for (const char* t : tables) {
        const auto start = std::chrono::steady_clock::now();
        const cdb::QueryResult r = conn.Query(std::string("COPY ") + t + " FROM '" + data_dir +
                                              "/" + t + ".csv' (DELIMITER '|', HEADER FALSE)");
        if (!r.ok()) {
            std::cerr << "loading " << t << ": " << r.error_message() << "\n";
            return 1;
        }
        std::printf("  %-9s %9lld rows  %7.2f s\n", t,
                    static_cast<long long>(r.GetValue(0, 0).GetBigInt()),
                    Seconds(std::chrono::steady_clock::now() - start));
    }
    std::printf("  peak RSS after load: %ld MB\n\n", MaxRssMb());

    std::printf("%-4s %8s %10s %10s %10s\n", "q", "rows", "cold ms", "min ms", "median ms");
    for (const int q : queries) {
        char name[16];
        std::snprintf(name, sizeof name, "q%02d", q);
        const std::string sql =
            ReadFile(std::string(CDB_SOURCE_DIR) + "/bench/tpch/queries/" + name + ".sql");
        std::vector<double> times;
        size_t rows = 0;
        for (int run = 0; run < runs; run++) {
            const auto start = std::chrono::steady_clock::now();
            const cdb::QueryResult r = conn.Query(sql);
            times.push_back(Seconds(std::chrono::steady_clock::now() - start) * 1000);
            if (!r.ok()) {
                std::cerr << name << ": " << r.error_message() << "\n";
                return 1;
            }
            rows = r.RowCount();
        }
        std::vector<double> sorted(times.begin() + (times.size() > 1 ? 1 : 0), times.end());
        std::sort(sorted.begin(), sorted.end());
        const size_t expected = ExpectedRows(data_dir + "/expected/" + name + ".csv");
        std::printf("%-4d %8zu %10.1f %10.1f %10.1f%s\n", q, rows, times[0], sorted.front(),
                    sorted[sorted.size() / 2],
                    expected && expected != rows ? "   ROW COUNT MISMATCH" : "");
    }
    std::printf("\npeak RSS: %ld MB\n", MaxRssMb());
    return 0;
}
